programa
{
    funcao inicio()
    {
        inteiro primeiro, segundo, total
        escreva("Primeiro inteiro: ")
        leia(primeiro)
        escreva("Segundo inteiro: ")
        leia(segundo)
        total = primeiro + segundo
        escreva("Total: ", total, "\n")
    }
}

