programa
{
    funcao inicio()
    {
        inteiro a, b, total
        escreva("Primeira quantidade: ")
        leia(a)
        escreva("Segunda quantidade: ")
        leia(b)
        total = a + b
        escreva("Total: ", total)
    }
}
